# rubik_solve_asm: optimal 2x2x2 cube solver, hand-written RV32I.
# a0 = state, a1 = out, a2 = cap; result in a0.
# Tables below are copied from depth5.h, moves.h and pdb.h.

    .text
    .globl  rubik_solve_asm
    .type   rubik_solve_asm, @function
    .align  2
rubik_solve_asm:
    addi    sp, sp, -48
    sw      ra, 44(sp)
    sw      s0, 40(sp)
    sw      s1, 36(sp)
    mv      s0, a1
    mv      s1, a2

    mv      a1, sp
    addi    a2, sp, 7
    call    .Lparse_state
    beqz    a0, .Linvalid

    mv      a0, sp
    call    .Lrank_permutation
    sw      a0, 28(sp)
    addi    a0, sp, 7
    call    .Lrank_orientation
    mv      a1, a0
    lw      a0, 28(sp)
    addi    a2, sp, 14
    call    .Lsolve
    bltz    a0, .Linvalid

    mv      t0, a0                 # length
    li      t1, 0                  # output position
    li      t2, 0                  # path index
    addi    t3, sp, 14
.Lformat_move:
    bge     t2, t0, .Lformat_done
    beqz    t2, .Lformat_name
    addi    t5, t1, 1
    bgeu    t5, s1, .Ltoo_small
    add     t6, s0, t1
    li      t4, 32
    sb      t4, 0(t6)
    mv      t1, t5
.Lformat_name:
    lbu     t4, 0(t3)
    slli    t4, t4, 2
    la      t5, .Lmove_names
    add     t5, t5, t4
    lw      a4, 0(t5)
.Lformat_char:
    lbu     a5, 0(a4)
    beqz    a5, .Lformat_next
    addi    t5, t1, 1
    bgeu    t5, s1, .Ltoo_small
    add     t6, s0, t1
    sb      a5, 0(t6)
    mv      t1, t5
    addi    a4, a4, 1
    j       .Lformat_char
.Lformat_next:
    addi    t2, t2, 1
    addi    t3, t3, 1
    j       .Lformat_move
.Lformat_done:
    bgeu    t1, s1, .Ltoo_small
    add     t6, s0, t1
    sb      zero, 0(t6)
    mv      a0, t0
    j       .Lreturn
.Ltoo_small:
    beqz    s1, .Ltoo_small_return
    sb      zero, 0(s0)
.Ltoo_small_return:
    li      a0, -2
    j       .Lreturn
.Linvalid:
    li      a0, -1
.Lreturn:
    lw      s1, 36(sp)
    lw      s0, 40(sp)
    lw      ra, 44(sp)
    addi    sp, sp, 48
    ret
    .size   rubik_solve_asm, .-rubik_solve_asm

    # int parse_state(input, p, o)
    # Check the length first, so short strings are never read past their NUL.
    .align  2
.Lparse_state:
    mv      t0, a0
    li      t1, 14
.Lparse_length:
    lbu     t2, 0(t0)
    beqz    t2, .Lparse_bad
    addi    t0, t0, 1
    addi    t1, t1, -1
    bnez    t1, .Lparse_length
    lbu     t2, 0(t0)
    bnez    t2, .Lparse_bad

    li      t0, 0                  # seen bit mask
    li      t1, 0                  # orientation sum
    li      t2, 7
.Lparse_cubie:
    lbu     t3, 0(a0)
    lbu     t4, 7(a0)
    addi    t3, t3, -49
    addi    t4, t4, -49
    sltiu   t5, t3, 7
    beqz    t5, .Lparse_bad
    sltiu   t5, t4, 3
    beqz    t5, .Lparse_bad
    li      t5, 1
    sll     t5, t5, t3
    and     t6, t0, t5
    bnez    t6, .Lparse_bad
    or      t0, t0, t5
    sb      t3, 0(a1)
    sb      t4, 0(a2)
    add     t1, t1, t4
    addi    a0, a0, 1
    addi    a1, a1, 1
    addi    a2, a2, 1
    addi    t2, t2, -1
    bnez    t2, .Lparse_cubie
    li      t0, 3
.Lparse_mod3:
    bltu    t1, t0, .Lparse_sum
    addi    t1, t1, -3
    j       .Lparse_mod3
.Lparse_sum:
    seqz    a0, t1
    ret
.Lparse_bad:
    li      a0, 0
    ret

    # Same lexicographic rank as the C available[] algorithm:
    # sum(number of later smaller elements * (6-i)!).
    # The tiny products use repeated addition, with no mul instruction.
    .align  2
.Lrank_permutation:
    li      t0, 0                  # rank
    li      t1, 0                  # i
    la      a1, .Lfactorials
    li      t6, 7
.Lrank_perm_outer:
    add     t2, a0, t1
    lbu     t2, 0(t2)
    addi    t3, t1, 1
    li      t4, 0                  # smaller count
.Lrank_perm_inner:
    bge     t3, t6, .Lrank_perm_weight
    add     t5, a0, t3
    lbu     t5, 0(t5)
    sltu    t5, t5, t2
    add     t4, t4, t5
    addi    t3, t3, 1
    j       .Lrank_perm_inner
.Lrank_perm_weight:
    lhu     a2, 0(a1)
.Lrank_perm_add:
    beqz    t4, .Lrank_perm_next
    add     t0, t0, a2
    addi    t4, t4, -1
    j       .Lrank_perm_add
.Lrank_perm_next:
    addi    a1, a1, 2
    addi    t1, t1, 1
    li      t5, 6
    blt     t1, t5, .Lrank_perm_outer
    mv      a0, t0
    ret

    .align  2
.Lrank_orientation:
    li      t0, 0
    li      t1, 6
.Lrank_ori_loop:
    lbu     t2, 0(a0)
    slli    t3, t0, 1
    add     t0, t3, t0
    add     t0, t0, t2
    addi    a0, a0, 1
    addi    t1, t1, -1
    bnez    t1, .Lrank_ori_loop
    mv      a0, t0
    ret

    # int near_distance(perm, ori): exact distance 0..5, or -1.
    .align  2
.Lnear_distance:
    la      t1, .Lnear_index
    slli    t2, a0, 1
    add     t1, t1, t2
    lhu     a2, 0(t1)              # lo
    lhu     a3, 2(t1)
    beq     a2, a3, .Lnear_missing
    addi    a3, a3, -1             # hi
    slli    t0, a0, 10
    or      t0, t0, a1             # key
    la      a4, .Lnear_states
.Lnear_loop:
    blt     a3, a2, .Lnear_missing
    add     t1, a2, a3
    srli    t1, t1, 1              # mid
    slli    t2, t1, 2
    add     t2, a4, t2
    lw      t3, 0(t2)
    srli    t4, t3, 3
    beq     t4, t0, .Lnear_found
    bltu    t4, t0, .Lnear_right
    addi    a3, t1, -1
    j       .Lnear_loop
.Lnear_right:
    addi    a2, t1, 1
    j       .Lnear_loop
.Lnear_found:
    andi    a0, t3, 7
    ret
.Lnear_missing:
    li      a0, -1
    ret

    # int descend(perm, ori, distance, path)
    .align  2
.Ldescend:
    addi    sp, sp, -48
    sw      ra, 44(sp)
    sw      s0, 40(sp)
    sw      s1, 36(sp)
    sw      s2, 32(sp)
    sw      s3, 28(sp)
    sw      s4, 24(sp)
    sw      s5, 20(sp)
    sw      s6, 16(sp)
    sw      s7, 12(sp)
    sw      s8, 8(sp)
    sw      s9, 4(sp)
    mv      s0, a0
    mv      s1, a1
    mv      s2, a2
    mv      s3, a3
    li      s4, 0
    la      s8, .Lturn_bases
    la      s9, .Lmove_turns
.Ldescend_step:
    beqz    s2, .Ldescend_done
    li      s5, 0
.Ldescend_move:
    la      t0, .Lmove_face
    add     t0, t0, s5
    lbu     t0, 0(t0)
    slli    t0, t0, 3
    add     t0, s8, t0
    lw      t3, 0(t0)              # permutation face table
    lw      t4, 4(t0)              # orientation face table
    add     t0, s9, s5
    lbu     t2, 0(t0)              # quarter-turn count
    mv      s6, s0
    mv      s7, s1
.Ldescend_turn:
    slli    t0, s6, 1
    add     t0, t3, t0
    lhu     s6, 0(t0)
    slli    t0, s7, 1
    add     t0, t4, t0
    lhu     s7, 0(t0)
    addi    t2, t2, -1
    bnez    t2, .Ldescend_turn
    mv      a0, s6
    mv      a1, s7
    call    .Lnear_distance
    addi    t0, s2, -1
    beq     a0, t0, .Ldescend_accept
    addi    s5, s5, 1
    li      t0, 9
    blt     s5, t0, .Ldescend_move
    li      a0, -1                 # unreachable for valid distance tables
    j       .Ldescend_return
.Ldescend_accept:
    add     t0, s3, s4
    sb      s5, 0(t0)
    addi    s4, s4, 1
    mv      s0, s6
    mv      s1, s7
    addi    s2, s2, -1
    j       .Ldescend_step
.Ldescend_done:
    mv      a0, s4
.Ldescend_return:
    lw      s9, 4(sp)
    lw      s8, 8(sp)
    lw      s7, 12(sp)
    lw      s6, 16(sp)
    lw      s5, 20(sp)
    lw      s4, 24(sp)
    lw      s3, 28(sp)
    lw      s2, 32(sp)
    lw      s1, 36(sp)
    lw      s0, 40(sp)
    lw      ra, 44(sp)
    addi    sp, sp, 48
    ret

    # int solve(start_perm, start_ori, path)
    # Iterative deepening, with the PDB checks inlined in the DFS.
    # Frame: perm[12] @0, ori[12] @24, next_moves[12] @48,
    # start_perm @60, start_ori @64; saved registers @76..127.
    .align  2
.Lsolve:
    addi    sp, sp, -128
    sw      ra, 124(sp)
    sw      s0, 120(sp)
    sw      s1, 116(sp)
    sw      s2, 112(sp)
    sw      s3, 108(sp)
    sw      s4, 104(sp)
    sw      s5, 100(sp)
    sw      s6, 96(sp)
    sw      s7, 92(sp)
    sw      s8, 88(sp)
    sw      s9, 84(sp)
    sw      s10, 80(sp)
    sw      s11, 76(sp)
    sw      a0, 60(sp)
    sw      a1, 64(sp)
    mv      s2, a2
    la      s3, .Lmove_face
    la      s4, .Lmove_turns
    la      s9, .Lpermutation_pdb
    la      s10, .Lorientation_pdb
    la      s11, .Lturn_bases

    # A hit gives the exact answer immediately. A miss proves distance > 5.
    call    .Lnear_distance
    bltz    a0, .Lsolve_far
    mv      a2, a0
    lw      a0, 60(sp)
    lw      a1, 64(sp)
    mv      a3, s2
    call    .Ldescend
    j       .Lsolve_return
.Lsolve_far:
    li      s0, 6                  # first possible bound
    lw      t0, 60(sp)
    add     t0, s9, t0
    lbu     t0, 0(t0)
    bge     s0, t0, .Lsolve_ori_bound
    mv      s0, t0
.Lsolve_ori_bound:
    lw      t0, 64(sp)
    add     t0, s10, t0
    lbu     t0, 0(t0)
    bge     s0, t0, .Lsolve_bound
    mv      s0, t0
.Lsolve_bound:
    li      t0, 11
    blt     t0, s0, .Lsolve_failed
    li      s1, 0                  # depth
    lw      t0, 60(sp)
    sh      t0, 0(sp)
    lw      t0, 64(sp)
    sh      t0, 24(sp)
    sb      zero, 48(sp)
.Lsolve_node:
    bltz    s1, .Lsolve_next_bound
    add     t0, sp, s1
    lbu     s7, 48(t0)
    li      t1, 9
    bge     s7, t1, .Lsolve_backtrack
    addi    t1, s7, 1
    sb      t1, 48(t0)
    add     t0, s3, s7
    lbu     s8, 0(t0)
    beqz    s1, .Lsolve_apply
    add     t0, s2, s1
    lbu     t0, -1(t0)
    add     t0, s3, t0
    lbu     t0, 0(t0)
    bne     t0, s8, .Lsolve_apply
    # The three moves of this face are consecutive: skip the whole group.
    addi    t1, s7, 3
    add     t0, sp, s1
    sb      t1, 48(t0)
    j       .Lsolve_node
.Lsolve_apply:
    slli    t0, s1, 1
    add     t0, sp, t0
    lhu     s5, 0(t0)
    lhu     s6, 24(t0)
    slli    t0, s8, 3
    add     t0, s11, t0
    lw      t3, 0(t0)
    lw      t4, 4(t0)
    add     t0, s4, s7
    lbu     t2, 0(t0)
.Lsolve_turn:
    slli    t0, s5, 1
    add     t0, t3, t0
    lhu     s5, 0(t0)
    slli    t0, s6, 1
    add     t0, t4, t0
    lhu     s6, 0(t0)
    addi    t2, t2, -1
    bnez    t2, .Lsolve_turn

    sub     t6, s0, s1
    addi    t6, t6, -1             # remaining = bound - depth - 1
    add     t0, s9, s5
    lbu     t0, 0(t0)
    blt     t6, t0, .Lsolve_node
    add     t0, s10, s6
    lbu     t0, 0(t0)
    blt     t6, t0, .Lsolve_node
    li      t0, 5
    blt     t0, t6, .Lsolve_expand

    mv      a0, s5
    mv      a1, s6
    call    .Lnear_distance
    bltz    a0, .Lsolve_node
    sub     t0, s0, s1
    addi    t0, t0, -1
    blt     t0, a0, .Lsolve_node
    mv      a2, a0                 # exact suffix distance
    add     t0, s2, s1
    sb      s7, 0(t0)
    addi    a3, t0, 1
    mv      a0, s5
    mv      a1, s6
    call    .Ldescend
    bltz    a0, .Lsolve_failed
    add     a0, a0, s1
    addi    a0, a0, 1
    j       .Lsolve_return
.Lsolve_expand:
    add     t0, s2, s1
    sb      s7, 0(t0)
    addi    s1, s1, 1
    slli    t0, s1, 1
    add     t0, sp, t0
    sh      s5, 0(t0)
    sh      s6, 24(t0)
    add     t0, sp, s1
    sb      zero, 48(t0)
    j       .Lsolve_node
.Lsolve_backtrack:
    addi    s1, s1, -1
    j       .Lsolve_node
.Lsolve_next_bound:
    addi    s0, s0, 1
    j       .Lsolve_bound
.Lsolve_failed:
    li      a0, -1
.Lsolve_return:
    lw      s11, 76(sp)
    lw      s10, 80(sp)
    lw      s9, 84(sp)
    lw      s8, 88(sp)
    lw      s7, 92(sp)
    lw      s6, 96(sp)
    lw      s5, 100(sp)
    lw      s4, 104(sp)
    lw      s3, 108(sp)
    lw      s2, 112(sp)
    lw      s1, 116(sp)
    lw      s0, 120(sp)
    lw      ra, 124(sp)
    addi    sp, sp, 128
    ret

    .section .rodata
.Lmove_face:
    .byte 0, 0, 0, 1, 1, 1, 2, 2, 2
.Lmove_turns:
    .byte 1, 2, 3, 1, 2, 3, 1, 2, 3
.Lname_R:
    .asciz "R"
.Lname_R2:
    .asciz "R2"
.Lname_Rprime:
    .asciz "R'"
.Lname_B:
    .asciz "B"
.Lname_B2:
    .asciz "B2"
.Lname_Bprime:
    .asciz "B'"
.Lname_D:
    .asciz "D"
.Lname_D2:
    .asciz "D2"
.Lname_Dprime:
    .asciz "D'"
    .align 2
.Lmove_names:
    .word .Lname_R, .Lname_R2, .Lname_Rprime
    .word .Lname_B, .Lname_B2, .Lname_Bprime
    .word .Lname_D, .Lname_D2, .Lname_Dprime
.Lturn_bases:
    .word .Lperm_turn, .Lori_turn
    .word .Lperm_turn + 10080, .Lori_turn + 1458
    .word .Lperm_turn + 20160, .Lori_turn + 2916
.Lfactorials:
    .half 720, 120, 24, 6, 2, 1

# Precomputed tables from the supplied C headers.

    .align 2
.Lnear_states:
    .word 0, 59669, 61693, 73733, 73857, 73917, 74597, 76493, 131073, 132229, 132629, 134333
    .word 135733, 147461, 147585, 147645, 149333, 152829, 190741, 192765, 204803, 204885, 204965, 205029
    .word 205253, 205940, 206196, 207421, 210037, 213149, 213261, 213293, 213395, 213621, 216404, 217764
    .word 246997, 247365, 259349, 278621, 278748, 278908, 281789, 283429, 284277, 286821, 286852, 287028
    .word 287812, 287973, 288133, 288213, 288477, 289516, 294949, 295044, 295229, 295333, 296013, 296116
    .word 296229, 296789, 297645, 305901, 307533, 311365, 311541, 313965, 319573, 319653, 319765, 319884
    .word 322933, 324349, 338429, 352364, 352588, 352597, 355429, 355613, 357141, 363141, 369821, 373829
    .word 376836, 377044, 377149, 377987, 378189, 379429, 390317, 394069, 394629, 404253, 409884, 410021
    .word 410085, 410197, 410277, 410333, 410997, 411204, 415045, 428477, 431421, 434565, 434628, 434812
    .word 437845, 439181, 439437, 450820, 451021, 451052, 453237, 455901, 467397, 467604, 468477, 468989
    .word 475444, 475525, 475621, 475812, 476613, 476677, 476805, 478285, 487821, 488781, 501389, 501445
    .word 503181, 507949, 508189, 508477, 508531, 508653, 509589, 510229, 513124, 516325, 516357, 516580
    .word 516829, 516957, 517717, 519021, 525029, 538293, 541421, 541453, 545405, 549181, 549277, 549349
    .word 549725, 550461, 566485, 568797, 573773, 573949, 574093, 576445, 576853, 579157, 582045, 582069
    .word 582164, 586957, 598172, 598285, 598420, 601173, 601429, 602789, 606405, 606453, 611413, 619645
    .word 630788, 630949, 631012, 631925, 632179, 636021, 647205, 647301, 647588, 647877, 648325, 648373
    .word 648484, 652533, 671812, 671988, 672237, 674413, 677077, 680020, 680213, 680333, 682981, 688235
    .word 688461, 688469, 688493, 688981, 689589, 691300, 692293, 704517, 704724, 704828, 705077, 705668
    .word 705868, 712757, 713133, 714045, 717996, 730269, 738885, 745501, 745901, 746845, 748253, 750029
    .word 750789, 770140, 770268, 770429, 770565, 773181, 775797, 778245, 778341, 778373, 778547, 779333
    .word 779732, 780349, 781037, 794908, 795044, 795109, 795301, 795333, 795781, 796021, 796228, 800068
    .word 803045, 803205, 803269, 803452, 806485, 807821, 812861, 813821, 823437, 830269, 835829, 836717
    .word 837316, 839637, 846037, 846637, 868637, 868925, 868980, 873573, 876772, 876805, 877028, 877405
    .word 877573, 877941, 878165, 879469, 882133, 885052, 885149, 885221, 885597, 886053, 886333, 890349
    .word 894269, 897741, 901453, 901629, 902349, 904124, 909725, 909749, 909845, 927477, 936733, 942340
    .word 942541, 942573, 944757, 952061, 959125, 966661, 966963, 967045, 967141, 967332, 968325, 971053
    .word 972229, 977685, 980301, 991237, 991684, 991892, 992765, 993277, 995317, 1002269, 1005109, 1007877
    .word 1008109, 1008469, 1009885, 1012957, 1013341, 1016325, 1016517, 1017149, 1018069, 1018781, 1021205, 1024309
    .word 1024485, 1024677, 1025477, 1025541, 1032197, 1032820, 1032940, 1033877, 1034516, 1037412, 1040869, 1041117
    .word 1048981, 1049141, 1049349, 1051597, 1070772, 1073685, 1073893, 1076085, 1081837, 1082197, 1082757, 1087069
    .word 1092380, 1098013, 1098325, 1098461, 1099125, 1099333, 1106437, 1106629, 1108181, 1111317, 1111565, 1122757
    .word 1122941, 1122965, 1124629, 1124717, 1127565, 1139253, 1139461, 1144357, 1147413, 1147621, 1149149, 1149813
    .word 1152205, 1156733, 1157981, 1158485, 1159229, 1160885, 1163893, 1164013, 1164045, 1165589, 1167997, 1168485
    .word 1179813, 1182269, 1184021, 1188413, 1198549, 1212547, 1212725, 1213508, 1213669, 1213829, 1214165, 1214173
    .word 1215213, 1220829, 1220989, 1221061, 1222397, 1223373, 1223869, 1226349, 1237389, 1237485, 1240437, 1245315
    .word 1245501, 1246285, 1246388, 1247060, 1256172, 1261693, 1261773, 1264124, 1286146, 1287284, 1287541, 1288005
    .word 1294637, 1294740, 1294964, 1296941, 1297748, 1298501, 1299109, 1299605, 1304949, 1313317, 1329837, 1331253
    .word 1332293, 1332645, 1337821, 1351683, 1351893, 1352835, 1353517, 1368173, 1368397, 1368597, 1371421, 1372141
